import { useNavigate } from "react-router-dom";
import { Publication } from "../../types";
import { Avatar, Box, Card, CardContent, CardHeader, CardMedia, Typography } from "@mui/material";
import { formatDistanceToNow } from "date-fns";
import LikeButton from "../Likes/LikeButton";
import CommentIcon from '@mui/icons-material/Comment'
import { fr } from "date-fns/locale";

interface PublicationCardProps {
    publication: Publication;
    currentUserId: number;
}

const PublicationCard: React.FC<PublicationCardProps> = ({publication, currentUserId}) => {
    const navigate = useNavigate();

    const avatarUrl = publication.photo_profil
        ? `http://localhost:8080/Icons/${publication.photo_profil}`
        : '/Icons/green.jpg';

    const photoUrl = publication.photo_publier
        ? `http://localhost:8080/uploads/${publication.photo_publier}`
        : null;

    return (
        <Card sx={{mb: 2, borderRadius: 3}}>
            <CardHeader
                avatar={
                    <Avatar src="{avatarUrl} sx={{width: 48, height: 48}}"/>
                }
                title={`@${publication.pseudo}`}
                subheader={formatDistanceToNow(new Date(publication.date), {
                    addSuffix: true,
                    locale: fr
                })}
            />

            {publication.contenu && (
                <CardContent>
                    <Typography variant="body1">{publication.contenu}</Typography>
                </CardContent>
            )}

            {photoUrl && (
                <CardMedia 
                    component="img"
                    image={photoUrl}
                    alt="Publication"
                    sx={{maxHeight: 400, objectFit: 'cober'}}
                />
            )}
            
            <CardContent>
                <Box display="flex" alignItems="center" gap={2}>
                    <LikeButton 
                        userId={currentUserId}
                        publicationId={publication.id}
                        initialCount={publication.nombre_like}
                    />

                    <Box
                        display="flex"
                        alignItems="center"
                        gap={0.5}
                        sx={{cursor: 'pointer'}}
                        onClick={() => navigate(`/commentaires?pubId=${publication.id}&userId=${currentUserId}`)}
                    >
                        <CommentIcon sx={{color: '#666'}}/>
                        <Typography variant="body2" color="text.secondary">
                            {publication.nombre_commentaire}
                        </Typography>
                    </Box>
                </Box>
            </CardContent>
        </Card>
    );
};

export default PublicationCard;
